from messer import Tool


def issue_credit_note(invoice_id: str, amount: float) -> dict:
    """Issue a credit note on a customer's invoice."""
    return billing.create_credit_note(invoice_id, amount)


# Credit notes over €500 wait for a human approval:
# the run pauses and resumes after the decision.
credit_note = Tool(
    handler=issue_credit_note,
    requires_approval=lambda amount, **_: amount > 500,
    approval_prompt=lambda invoice_id, amount, **_: (
        f"Issue a €{amount} credit note on {invoice_id}?"
    ),
)
